import java.util.Scanner;

public class SoftDrinking {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int l = scanner.nextInt();
        int c = scanner.nextInt();
        int d = scanner.nextInt();
        int p = scanner.nextInt();
        int nl = scanner.nextInt();
        int np = scanner.nextInt();

        // Total amount of drink in milliliters
        int totalDrink = k * l;
        // Total number of toasts possible from drink
        int toastsFromDrink = totalDrink / nl;

        // Total number of lime slices
        int totalSlices = c * d;
        // Total number of toasts possible from limes
        int toastsFromLimes = totalSlices;

        // Total number of toasts possible from salt
        int toastsFromSalt = p / np;

        // Maximum total toasts possible limited by the most constrained resource
        int totalToasts = Math.min(toastsFromDrink, Math.min(toastsFromLimes, toastsFromSalt));

        // Number of toasts each friend can make
        int toastsPerFriend = totalToasts / n;

        System.out.println(toastsPerFriend);
    }
}
